#!/usr/bin/env python3
"""
Round 119b (culprits), 30 September 2026. Needs round 118b.

The attacks rows in English and grouped as like layers (also under Invasion
of humans), filters by their own fields, areas in conflict as municipalities,
homicides worldwide, Wreckers of the Earth by Corporate Watch's sections, the
largest companies' boards in place of They Rule's page, EJAtlas categories by
name, sharper points and lighter raised shading, WJP's 2022 map, every trade
flow.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

DIFF = ''
NOTE = '## Round 119b (30 September)\n\nNeeds round 118b. Tiles patch round119b_tiles.py beside it. No app.js?v= bump.\n\n- Attacks rows read attacks/plain/*.geojson (tiles attacks_plain.py) first,\n  the originals until built (files[].fallback in readGeojsonFiles): labels in\n  English from a table of the sources\' terms, longer texts machine-translated\n  with Argos Translate on the build machine (cached in\n  attacks/plain/translations.json, a time budget per run, so CIMI\'s 9,202\n  cases fill in over several days), Brazil\'s state codes as names, the Land\n  of Resistance\'s record dates as dates ("added to the database on"), CIMI\'s\n  cases by family of violence (report chapter), Front Line Defenders\' tags\n  in English. Areas in land conflict drawn as municipalities (cgaz-boundaries\n  BRA2, state rows as BRA), one shape per municipality and year, year bar.\n- filterBy (filterByTokens): chips by a row\'s own fields, list fields under\n  each value; groupLabel names the kind chips (default "Kind", was "Layer").\n  gw_killings coloured and filtered by who killed them; land_of_resistance,\n  frontline (rights at stake, violations), cimi, CPT rows likewise.\n- Bundles killing_indigenous, defenders, brazil_land, homicides under\n  Destruction > Of individuals > Of humans and again under Invasion of humans\n  > Conflicts and killings. Water conflicts under Water scarcity;\n  overexploitation under Slavery\'s cases and enforcement.\n- Homicides: homicide_rates (World Bank VC.IHR.PSRC.P5, UNODC), homicide_cases\n  (mvtlive tiles/homicide_cases.pmtiles: Chicago, LA, NYC, Washington Post 50\n  cities), homicide_colombia (towns), homicide_wikidata; tiles homicides.py.\n- Wreckers: one layer (bundle wreckers), London uMap and worldwide; worldwide\n  grouped by Corporate Watch\'s own directory sections (tiles\n  troutwood_layers.py), tobacco, airlines and shipping out, arms makers kept\n  as Corporate Watch lists them; the company box says why it is on the layer.\n- They Rule\'s page replaced by boards_interlocks (tiles boards.py: Wikidata\n  board members, chairs and chief executives of the 500 largest companies,\n  lines between companies sharing a person). EJAtlas below it, its ten\n  categories named (EJ_CATEGORIES) and coloured.\n- AUTO_GROUP_COLOURS 24; kinds past the colours said in the key; years in\n  colour keys without commas; "as the row draws them" now "its own colours".\n- Raised rows\' hillshade lighter and gone by zoom 7.5 (the dark grey\n  shading); glow cores and dots sharp (blur 0.12/0.15, cores at least\n  1.8 px).\n- WJP: wjp_discrimination_2022 (score_2022, ranks per edition, tiles\n  wjp_discrimination.py). Global Witness countries: totals without the\n  chart\'s LAT/LON, columns named (global_witness.py).\n- rte_trade reads every flow (rte/trades_all_<year>.json, tiles rte.py) and\n  shows every flow by default; carbon plumes read every page; Launch Library\n  up to 60 pages.\n\n'
HEAD = "## Round 119b (30 September)"


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round119b: run from the culprits repository root")
    text = (root / "HANDOFF.md").read_text(encoding="utf-8")
    if "## Round 118b" not in text:
        sys.exit("round119b: round 118b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round119b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            sys.exit("round119b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round119b: applied")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        # Above the newest note, whichever chat wrote it.
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
